{
  "Q1": {
    "q1_duty_procs": {
      "verdict": "yes",
      "rationale": "Lists 11046 (2026-14991), 11047 (2026-14992), 11048 (2026-14997), each signed July 20, 2026 and published July 23, 2026."
    },
    "q1_details": {
      "verdict": "yes",
      "rationale": "Gives all ten first pages correctly (46639, 46653, 46663, 54789, 58311, 58319, 58325, 58331, 58339, 68861) with a one-line description of each."
    },
    "q1_delay": {
      "verdict": "yes",
      "rationale": "11056 (2026-17294), signed Aug. 18, published Aug. 24; moves the effective date of all three duties to 12:01 a.m. Aug. 22, 2026 from Aug. 19."
    },
    "q1_exclusions": {
      "verdict": "yes",
      "rationale": "11061/11062/11063 (2026-18835/-18836/-18837), signed Sept. 8, published Sept. 14, operative time 12:01 a.m. Sept. 29, 2026 measured against importation."
    },
    "q1_scope": {
      "verdict": "yes",
      "rationale": "11064 and 11065 (2026-18838/-18839), signed Sept. 8, applying from Sept. 15; 11076 (2026-22292), signed Oct. 23, published Oct. 30, applying from Oct. 30."
    },
    "q1_events": {
      "verdict": "yes",
      "rationale": "States duties and scope changes are measured against entry for consumption or withdrawal from warehouse, while the exclusions are measured against importation ('imported on or after')."
    },
    "q1_dairy_none": {
      "verdict": "yes",
      "rationale": "Says dairy was changed only by 11047 and 11062 and that no dairy scope proclamation was published; attributes scope changes to 11064 (alcohol), 11065/11076 (motor vehicles)."
    },
    "q1_dairy_xref": {
      "verdict": "yes",
      "rationale": "Uncertainty field notes 11062 cl. (3) refers to a Sept. 8 dairy scope proclamation and that no such document appears in the Federal Register."
    },
    "q1_cite": {
      "verdict": "no",
      "rationale": "Claims are extensively cited to FR documents, clauses and pages."
    },
    "q1_fab": {
      "verdict": "no",
      "rationale": "Checked 11056 filing line ('Filed 8-21-26'), pages and document numbers; no invented source or unverifiable quotation found."
    }
  },
  "Q2": {
    "q2a_zero": {
      "verdict": "yes",
      "rationale": "Entry 1 (Aug. 20) and entry 2 (11:59 p.m. Aug. 21) are both $0."
    },
    "q2a_third": {
      "verdict": "yes",
      "rationale": "Entry 3 (12:01 a.m. Aug. 22) owes $40,000 x 50% = $20,000."
