    },
    "q2b_chapeau": {
      "verdict": "yes",
      "rationale": "Says 11056 amended only the chapeau of Annex II (deleting Aug. 19 and inserting Aug. 22) and that the body clauses (naming clauses (1) and (3) of 11046) still print Aug. 19."
    },
    "q2b_resolve": {
      "verdict": "yes",
      "rationale": "Identifies both the first sentence of 11056 cl. (1) and the supersession clause (5) as resolving the leftover Aug. 19 text."
    },
    "q2c_refund": {
      "verdict": "yes",
      "rationale": "Quotes 11056 cl. (4) (refunds under applicable law and CBP's standard procedures) and adds cl. (2) suspension of collection."
    },
    "q2d_no_action": {
      "verdict": "yes",
      "rationale": "Says no further presidential action was needed and cites later recitals that the 3-day suspension lapsed at 12:01 a.m. Aug. 22 and the duties became effective."
    },
    "q2d_reneged": {
      "verdict": "yes",
      "rationale": "States Canada expressed a commitment, then on Aug. 21, 2026 'reneged on its commitment, ceased negotiating in good faith,' citing 11061 recitals at 91 FR 58311."
    },
    "q2e_thirty": {
      "verdict": "yes",
      "rationale": "Explains July 20 plus 30 days = Aug. 19 under the recited section 338 30-day rule."
    },
    "q2_cite": {
      "verdict": "no",
      "rationale": "All major claims carry FR document, clause and page citations."
    },
    "q2_fab": {
      "verdict": "no",
      "rationale": "Quotations checked against 11056 and 11061; they match. No invented source."
    }
  },
